import{_ as s,o as i,c as e,a3 as t}from"./chunks/framework.WFmvnizL.js";const k=JSON.parse('{"title":"如何启用 TSDB","description":"哪吒监控 V2 官方文档：如何启用 TSDB。了解相关功能、配置步骤、使用场景、权限边界和常见问题，并查看 Dashboard 与 Agent 的准确说明。","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"guide/q15.md","filePath":"guide/q15.md","lastUpdated":1792674226000}'),d={name:"guide/q15.md"};function l(h,a,n,p,o,r){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="如何启用-tsdb" tabindex="-1">如何启用 TSDB <a class="header-anchor" href="#如何启用-tsdb" aria-label="Permalink to &quot;如何启用 TSDB&quot;">​</a></h1><p>TSDB 默认关闭。Dashboard 只有在配置了 <code>tsdb.data_path</code> 后才会初始化内置的 VictoriaMetrics 存储。</p><h2 id="适用范围" tabindex="-1">适用范围 <a class="header-anchor" href="#适用范围" aria-label="Permalink to &quot;适用范围&quot;">​</a></h2><p>启用 TSDB 后，服务器详情页的历史指标图表可以查询 1 天、7 天、30 天等历史周期；未启用时，前端会锁定这些历史周期。</p><p>服务监控历史在未启用 TSDB 时仍会从数据库读取；启用后会改为从 TSDB 查询。</p><h2 id="配置方式" tabindex="-1">配置方式 <a class="header-anchor" href="#配置方式" aria-label="Permalink to &quot;配置方式&quot;">​</a></h2><p>编辑 Dashboard 配置文件，通常是 <code>/opt/nezha/dashboard/data/config.yaml</code>，增加或修改：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tsdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  data_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/tsdb&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  retention_days</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  min_free_disk_space_gb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_memory_mb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">256</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  write_buffer_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">512</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  write_buffer_flush_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span></code></pre></div><p><code>data_path</code> 可以填写相对路径或绝对路径。相对路径会按 Dashboard 运行目录解析。此项为空时 TSDB 不会启用。</p><p>也可以使用环境变量启用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NZ_TSDB_DATA_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">data/tsdb</span></span></code></pre></div><p>修改配置后需要重启 Dashboard。</p><h2 id="如何确认已启用" tabindex="-1">如何确认已启用 <a class="header-anchor" href="#如何确认已启用" aria-label="Permalink to &quot;如何确认已启用&quot;">​</a></h2><p>重启后查看 Dashboard 日志：</p><ul><li>出现 <code>TSDB initialized successfully</code>：TSDB 已启用。</li><li>出现 <code>TSDB is disabled (tsdb.data_path not configured)</code>：未配置 <code>data_path</code>，TSDB 仍关闭。</li></ul><p>前端也会通过系统配置接口读取 <code>tsdb_enabled</code>。如果该值为 <code>false</code>，服务器详情页的历史指标周期会保持锁定。</p><h2 id="磁盘空间不足时的行为" tabindex="-1">磁盘空间不足时的行为 <a class="header-anchor" href="#磁盘空间不足时的行为" aria-label="Permalink to &quot;磁盘空间不足时的行为&quot;">​</a></h2><p>Dashboard 对磁盘空间不足进行降级处理：</p><ul><li>低于 <code>min_free_disk_space_gb</code> 导致存储进入只读时，暂停并丢弃新指标写入，已有历史仍可查询；空间恢复、存储退出只读后自动恢复写入。</li><li>写入或刷盘时遇到真正的磁盘满/配额耗尽错误，会停写至 Dashboard 重启。先释放磁盘空间，再重启 Dashboard。</li><li>启动时 TSDB 因磁盘满无法初始化，Dashboard 会继续运行，并尝试准备 SQLite 服务监控历史存储；本次进程未启用 TSDB，<code>tsdb_enabled</code> 为 <code>false</code>。释放空间并重启后才能重新打开 TSDB。</li></ul><p>日志中的 <code>TSDB writes paused</code>、<code>TSDB writes resumed</code> 和 <code>TSDB disk is full</code> 可帮助区分以上情况。停写期间的数据不会排队等待补写，因此历史曲线可能有缺口。降级不会把既有 TSDB 历史迁回 SQLite；Dashboard 的降级保护也不代表同一磁盘上的 SQLite 仍有足够空间写入。</p><p><a href="/guide/servers.html#在线历史">服务器在线历史</a> 使用独立的数据库会话记录，不受 TSDB 指标保留期控制，也不要求启用 TSDB。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>启用 TSDB 后，Dashboard 会删除旧的 <code>service_histories</code> 数据库表，已有服务监控历史不会自动迁移到 TSDB。建议在启用前先备份数据库。</p><p>TSDB 使用本地磁盘存储，请确保 <code>data_path</code> 所在分区有足够空间，并根据保留天数和服务器数量调整 <code>retention_days</code>、<code>min_free_disk_space_gb</code> 和 <code>max_memory_mb</code>。</p>`,24)])])}const b=s(d,[["render",l]]);export{k as __pageData,b as default};
